def asana_get_task(id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0377000" if __import__("os").path.isdir("./environment_mix/0377000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    status = "ok"

    # Validate input
    if not isinstance(id, str):
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "id must be a string", field="id")
    elif not id.strip():
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "id is required", field="id")
    else:
        w = _load("world.json")
        if not isinstance(w, dict):
            w = {}
        tasks = w.get("tasks", [])
        if not isinstance(tasks, list):
            tasks = []
        task = next((t for t in tasks if isinstance(t, dict) and t.get("id") == id), None)
        if not task:
            status = "not_found"
            resp = _err("NOT_FOUND", "Task not found", id=id)
        else:
            resp = {"task": task}

    # Record usage/audit (create local audit collection if none exists)
    try:
        audit = _load("usage.json")
        if not isinstance(audit, dict):
            audit = {}
        audit.setdefault("requests", [])
        if not isinstance(audit["requests"], list):
            audit["requests"] = []
        audit.setdefault("counters", {})
        if not isinstance(audit["counters"], dict):
            audit["counters"] = {}

        now = datetime.datetime.utcnow()
        latency_ms = int((now - start).total_seconds() * 1000)
        audit["requests"].append({
            "ts": now.replace(microsecond=0).isoformat() + "Z",
            "endpoint": "asana_get_task",
            "status": status,
            "latency_ms": latency_ms
        })
        audit["counters"]["total_requests"] = int(audit["counters"].get("total_requests", 0)) + 1
        key = "requests_by_endpoint:asana_get_task"
        audit["counters"][key] = int(audit["counters"].get(key, 0)) + 1
        _save("usage.json", audit)
    except Exception:
        return _err("CONFLICT", "Failed to record request usage")

    return resp

def asana_create_task(name, project_id, assignee=None, due_on=None, **_extra):
    import json, os, datetime, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0377000" if __import__("os").path.isdir("./environment_mix/0377000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    status = "ok"

    # Validate inputs
    if not isinstance(name, str):
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "name must be a string", field="name")
    elif not name.strip():
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "name cannot be blank", field="name")
    elif not isinstance(project_id, str):
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")
    elif not project_id.strip():
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "project_id is required", field="project_id")
    elif due_on is not None and not isinstance(due_on, str):
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "due_on must be a string in YYYY-MM-DD", field="due_on")
    elif due_on is not None:
        try:
            datetime.datetime.strptime(due_on, "%Y-%m-%d")
            resp = None
        except ValueError:
            status = "validation_error"
            resp = _err("VALIDATION_ERROR", "due_on must be in YYYY-MM-DD format", field="due_on")
    else:
        resp = None

    if resp is None:
        if assignee is not None:
            if not isinstance(assignee, str) or not assignee.strip():
                status = "validation_error"
                resp = _err("VALIDATION_ERROR", "assignee must be a non-empty string email when provided", field="assignee")
            else:
                # Basic email validation
                if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", assignee.strip()):
                    status = "validation_error"
                    resp = _err("VALIDATION_ERROR", "assignee must be a valid email address", field="assignee")

    w = _load("world.json")
    if not isinstance(w, dict):
        w = {}

    if resp is None:
        projects = w.get("projects", [])
        if not isinstance(projects, list):
            projects = []
        proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
        if not proj:
            status = "not_found"
            resp = _err("NOT_FOUND", "Project not found", project_id=project_id)
        else:
            if proj.get("status") != "active":
                status = "invalid_transition"
                resp = _err("INVALID_TRANSITION", "Project is not active/writable", project_id=project_id, status=proj.get("status"))

    created_task = None
    if resp is None:
        tasks = w.get("tasks", [])
        if not isinstance(tasks, list):
            tasks = []
            w["tasks"] = tasks

        # Generate unique task id
        existing_ids = {t.get("id") for t in tasks if isinstance(t, dict)}
        new_id = None
        # Prefer a readable T-<n> format, fall back to uuid
        for i in range(1, 1000000):
            cand = f"T-{i}"
            if cand not in existing_ids:
                new_id = cand
                break
        if new_id is None:
            new_id = "T-" + uuid.uuid4().hex[:12]

        created_task = {
            "id": new_id,
            "name": name.strip(),
            "project_id": project_id,
            "assignee": assignee.strip() if isinstance(assignee, str) else (assignee if assignee is None else str(assignee)),
            "due_on": due_on,
            "completed": False,
            "priority": "normal",
        }
        tasks.append(created_task)

        try:
            _save("world.json", w)
            resp = {"task": created_task}
        except Exception:
            status = "conflict"
            resp = _err("CONFLICT", "Failed to persist task creation")

    # Record usage/audit
    try:
        audit = _load("usage.json")
        if not isinstance(audit, dict):
            audit = {}
        audit.setdefault("requests", [])
        if not isinstance(audit["requests"], list):
            audit["requests"] = []
        audit.setdefault("counters", {})
        if not isinstance(audit["counters"], dict):
            audit["counters"] = {}

        now = datetime.datetime.utcnow()
        latency_ms = int((now - start).total_seconds() * 1000)
        audit["requests"].append({
            "ts": now.replace(microsecond=0).isoformat() + "Z",
            "endpoint": "asana_create_task",
            "status": status,
            "latency_ms": latency_ms
        })
        audit["counters"]["total_requests"] = int(audit["counters"].get("total_requests", 0)) + 1
        key = "requests_by_endpoint:asana_create_task"
        audit["counters"][key] = int(audit["counters"].get(key, 0)) + 1
        _save("usage.json", audit)
    except Exception:
        return _err("CONFLICT", "Failed to record request usage")

    return resp

