def slack_send_channel_message(channel_id, text, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0377000" if __import__("os").path.isdir("./environment_mix/0377000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()
    status = "ok"

    # Validate inputs
    valid_channels = {"C_GEN", "C_INC", "C_OPS", "C_VENDOR"}
    if not isinstance(channel_id, str):
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "channel_id must be a string", field="channel_id")
    elif not channel_id.strip():
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "channel_id is required", field="channel_id")
    elif channel_id not in valid_channels:
        status = "not_found"
        resp = _err("NOT_FOUND", "Unknown channel_id", channel_id=channel_id)
    elif not isinstance(text, str):
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "text must be a string", field="text")
    elif not text.strip():
        status = "validation_error"
        resp = _err("VALIDATION_ERROR", "text cannot be blank", field="text")
    else:
        w = _load("world.json")
        if not isinstance(w, dict):
            w = {}
        channels = w.get("channels", [])
        if not isinstance(channels, list):
            channels = []
            w["channels"] = channels
        messages = w.get("messages", [])
        if not isinstance(messages, list):
            messages = []
            w["messages"] = messages

        ch = next((c for c in channels if isinstance(c, dict) and c.get("id") == channel_id), None)
        if not ch:
            status = "not_found"
            resp = _err("NOT_FOUND", "Channel not found", channel_id=channel_id)
        elif bool(ch.get("is_private")):
            status = "unauthorized"
            resp = _err("UNAUTHORIZED", "No access to private channel", channel_id=channel_id)
        else:
            ts = f"{time.time():.6f}"
            bot_user_id = w.get("bot_user_id") if isinstance(w.get("bot_user_id"), str) else "U_BOT"
            msg = {
                "id": None,
                "ts": ts,
                "channel_id": channel_id,
                "user_id": bot_user_id,
                "text": text,
                "thread_ts": None,
                "reply_count": 0,
                "is_bot": True,
                "reactions": []
            }
            messages.append(msg)
            try:
                _save("world.json", w)
                resp = {"message": msg}
            except Exception:
                status = "conflict"
                resp = _err("CONFLICT", "Failed to persist message")

    # Record usage/audit
    try:
        audit = _load("usage.json")
        if not isinstance(audit, dict):
            audit = {}
        audit.setdefault("requests", [])
        if not isinstance(audit["requests"], list):
            audit["requests"] = []
        audit.setdefault("counters", {})
        if not isinstance(audit["counters"], dict):
            audit["counters"] = {}

        now = datetime.datetime.utcnow()
        latency_ms = int((now - start).total_seconds() * 1000)
        audit["requests"].append({
            "ts": now.replace(microsecond=0).isoformat() + "Z",
            "endpoint": "slack_send_channel_message",
            "status": status,
            "latency_ms": latency_ms
        })
        audit["counters"]["total_requests"] = int(audit["counters"].get("total_requests", 0)) + 1
        key = "requests_by_endpoint:slack_send_channel_message"
        audit["counters"][key] = int(audit["counters"].get(key, 0)) + 1
        _save("usage.json", audit)
    except Exception:
